#include <QQmlContext>
#include <QQuickWindow>
#include <QQuickItem>
#include "TrayController.h"
#include <QDBusConnection>
#include <QDBusConnectionInterface>
#include <QJsonDocument>
#include <QFile>
#include <QSystemTrayIcon>
#include <QGuiApplication>
